// Producer entrypoint: `services.ts` enqueues here instead of writing to the
// DB directly. id/createdAt are generated by the producer so the SK is
// deterministic downstream (worker needs no lookup to UpdateItem).

import { Queue } from "bullmq";
import { connection } from "./connection.js";

export type SendMessageJob = {
	conversationId: string;
	messageId: string;
	body: string;
	senderId: string;
	senderName: string;
	createdAt: string;
};

export const messageQueue = new Queue<SendMessageJob>("send-message", {
	connection,
});
